            List<NodeAnchor> latinFontSlots=new ArrayList<>();for(Object value:DraftBusinessRules.list(entry.get("latinFontSlotParagraphs")))latinFontSlots.add(anchor(index,DraftBusinessRules.asMap(value),"paragraph"));
            List<NodeAnchor> cellKeepNext=new ArrayList<>(),cellWidows=new ArrayList<>();for(Object value:DraftBusinessRules.list(entry.get("cellKeepNextParagraphs")))cellKeepNext.add(cellFlowAnchor(index,DraftBusinessRules.asMap(value)));for(Object value:DraftBusinessRules.list(entry.get("cellWidowParagraphs")))cellWidows.add(cellFlowAnchor(index,DraftBusinessRules.asMap(value)));
            List<NodeAnchor> bodyWidows=new ArrayList<>();for(Object value:DraftBusinessRules.list(entry.get("bodyWidowParagraphs")))bodyWidows.add(anchor(index,DraftBusinessRules.asMap(value),"paragraph"));
