    private static NodeAnchor anchor(TemplateIndex index,Map<String,Object> entry,String prefix){NodeAnchor node=index.anchor(String.valueOf(entry.get(prefix+"Id")));if(!node.getSha256().equals(entry.get(prefix+"Sha256")))throw new IllegalStateException("Native layout registry anchor mismatch: "+node.getId());return node;}
    private static NodeAnchor cellFlowAnchor(TemplateIndex index,Map<String,Object> entry){String id=String.valueOf(entry.get("paragraphId"));Paragraph paragraph=index.paragraph(id);if(paragraph.getCellId()==null&&!paragraph.getText().isEmpty()||!DraftPdfConverter.sha256(paragraph.getText().getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(entry.get("paragraphTextSha256")))throw new IllegalStateException("Native cell flow registry paragraph mismatch: "+id);return index.anchor(id);}
    static Map<String,Object> info(String key,String rendererKind,DocxEditResult result) {
        Map<String,Object> registry=rendererRegistry(rendererKind);if(!("NTT".equals(key)||"SCT".equals(key)||"SCC".equals(key))||registry==null&&result.getNativeStoryLedger().isEmpty())return null;if(registry==null)registry=Collections.singletonMap("version",DraftNativeIdentity.INTEGRATION_VERSION);
        List<Object> actions=new ArrayList<>();for(NativeLayoutChange change:result.getNativeLayoutLedger())actions.add(DraftBusinessRules.map("action",change.getAction(),"status",change.getStatus(),"sourceId",change.getSource().getId(),"sourceNodeSha256",change.getSource().getSha256(),"generatedId",change.getGeneratedId(),"layoutId",change.getLayoutId()));
        return DraftBusinessRules.map("kind","native_layout","profile",result.getNativeLayoutProfile()==null?registry.get("version"):result.getNativeLayoutProfile(),"status",result.getNativeLayoutProfile()==null?"skipped_unverified_source":"applied","sourceSha256",result.getOriginalSourceSha256(),"docxSha256",result.getDocxSha256(),"compiledDocxSha256",result.getDocxSha256(),"actions",actions,"nativeStories",nativeStories(result),"bodyLayoutStatus",result.getNativeLayoutProfile()!=null&&result.getNativeLayoutProfile().endsWith(":story-only")?"not_verified":"existing_source_bound_policy","message",result.getNativeLayoutProfile()==null||result.getNativeLayoutProfile().endsWith(":story-only")?com.consense.common.LocalizedText.of("此模板版本未应用已核验的续页布局；原生内容与控件已保留。","此範本版本未套用已核驗的續頁佈局；原生內容與控制項已保留。","Verified continuation layout was skipped for this source edition; native content and controls are preserved."):null);
    }
    private static Map<String,Object> nativeStories(DocxEditResult result){if(result.getNativeStoryLedger().isEmpty())return null;Map<String,String> parts=new LinkedHashMap<>();for(Map.Entry<String,String> entry:result.getIndex().getEntryHashes().entrySet())if(entry.getKey().matches("word/(header[0-9]+|footer[0-9]+)\\.xml")||Arrays.asList("word/_rels/document.xml.rels","[Content_Types].xml","word/styles.xml","word/settings.xml").contains(entry.getKey()))parts.put(entry.getKey(),entry.getValue());return DraftBusinessRules.map("kind","native_story","version",DraftNativeIdentity.INTEGRATION_VERSION,"status","applied","sourceSha256",result.getOriginalSourceSha256(),"docxSha256",result.getDocxSha256(),"compiledDocxSha256",result.getDocxSha256(),"entryHashes",parts,"actions",result.getNativeStoryLedger());}
    static List<Object> ledger(DocxEditResult result,Map<String,Object> layout){List<Object> rows=new ArrayList<>(result.getLedger());if(layout!=null)rows.add(layout);return rows;}
    static List<Object> savedLedger(DraftArtifact artifact,java.util.function.Function<String,DraftArtifact> lookup){
        List<Object> rows=JsonUtils.readList(artifact.getLedgerJson(),Object.class);Map<String,String> wanted=new LinkedHashMap<>();
        for(Object raw:rows){Map<String,Object> receipt=DraftBusinessRules.asMap(raw);if("body_scope_cleanup".equals(receipt.get("kind"))&&!DraftBodyCleanup.verifiedSavedTransition(String.valueOf(receipt.get("savedDocxSha256")),artifact.getDocxSha256(),rows)){String id=String.valueOf(receipt.get("savedRevisionId")),hash=String.valueOf(receipt.get("savedDocxSha256"));if(!hash.matches("[a-f0-9]{64}")||id.isEmpty()||"null".equals(id)||wanted.containsKey(id)&&!hash.equals(wanted.get(id)))throw new IllegalStateException("BODY_SCOPE_SAVED_LINEAGE_UNVERIFIED");wanted.put(id,hash);}}
        if(wanted.isEmpty())return rows;List<Object> recovered=new ArrayList<>(rows);Set<String> visited=new HashSet<>();DraftArtifact child=artifact;
        while(!wanted.isEmpty()){
            if(child==null||child.getId()==null||!visited.add(child.getId())||!Objects.equals(artifact.getProjectId(),child.getProjectId())||!Objects.equals(artifact.getFileKey(),child.getFileKey())||!Objects.equals(artifact.getSnapshotId(),child.getSnapshotId())||!Objects.equals(artifact.getSourceSha256(),child.getSourceSha256())||!Objects.equals(child.getDocxSha256(),DraftPdfConverter.sha256(child.getDocxBytes())))throw new IllegalStateException("BODY_SCOPE_SAVED_LINEAGE_UNVERIFIED");
            if(wanted.containsKey(child.getId())){if(!wanted.remove(child.getId()).equals(child.getDocxSha256()))throw new IllegalStateException("BODY_SCOPE_SAVED_LINEAGE_UNVERIFIED");if(wanted.isEmpty())break;}
            String parentId=child.getParentRevisionId();DraftArtifact parent=parentId==null?null:lookup.apply(parentId);if(parent==null||!parentId.equals(parent.getId())||!Objects.equals(artifact.getProjectId(),parent.getProjectId())||!Objects.equals(artifact.getFileKey(),parent.getFileKey())||!Objects.equals(artifact.getSnapshotId(),parent.getSnapshotId())||!Objects.equals(artifact.getSourceSha256(),parent.getSourceSha256())||!Objects.equals(parent.getDocxSha256(),DraftPdfConverter.sha256(parent.getDocxBytes())))throw new IllegalStateException("BODY_SCOPE_SAVED_LINEAGE_UNVERIFIED");
            recovered.add(DraftBusinessRules.map("kind","saved_artifact_derivation","status","VERIFIED_IMMUTABLE_ARTIFACT_PARENT","projectId",artifact.getProjectId(),"fileKey",artifact.getFileKey(),"snapshotId",artifact.getSnapshotId(),"sourceSha256",artifact.getSourceSha256(),"parentRevisionId",parent.getId(),"revisionId",child.getId(),"parentDocxSha256",parent.getDocxSha256(),"docxSha256",child.getDocxSha256()));
            recovered=DraftBodyCleanup.preserveHistory(parent.getLedgerJson(),recovered);child=parent;
        }
        return recovered;
    }
    static Map<String,Object> savedInfo(String json,String key,String rendererKind,String sourceHash,String docxHash) {
        for(Object raw:JsonUtils.readList(json,Object.class)){Map<String,Object> row=DraftBusinessRules.asMap(raw);if("native_layout".equals(row.get("kind")))return new LinkedHashMap<>(row);}
        Map<String,Object> registry=rendererRegistry(rendererKind);if(registry==null||!("NTT".equals(key)||"SCT".equals(key)||"SCC".equals(key)))return null;
        return DraftBusinessRules.map("kind","native_layout","profile",registry.get("version"),"status","not_applied_to_saved_revision","sourceSha256",sourceHash,"docxSha256",docxHash,"actions",Collections.emptyList(),"message",com.consense.common.LocalizedText.of("此已保存版本没有已记录的续页布局修正；现有正文和版本保持不变。","此已儲存版本沒有已記錄的續頁佈局修正；現有正文和版本保持不變。","This saved revision has no recorded continuation layout repair; its current body and revision remain unchanged."));
    }
    static List<Object> bodyLedger(String previousJson,DocxEditResult result) {
        Map<String,Object> previous=null;for(Object raw:JsonUtils.readList(previousJson,Object.class)){Map<String,Object> row=DraftBusinessRules.asMap(raw);if("native_layout".equals(row.get("kind")))previous=row;}
        if(previous==null)return DraftBodyCleanup.preserveHistory(previousJson,ledger(result,null));Map<String,Object> current=new LinkedHashMap<>(previous);current.put("parentDocxSha256",previous.get("docxSha256"));current.put("docxSha256",result.getDocxSha256());List<Object> actions=new ArrayList<>();
        Map<String,List<Feature>> markers=new HashMap<>();for(Feature feature:result.getIndex().getFeatures())if("BOOKMARK".equals(feature.getKind())&&"word/document.xml".equals(feature.getPart()))markers.computeIfAbsent(feature.getName(),id->new ArrayList<>()).add(feature);
        for(Object raw:DraftBusinessRules.list(previous.get("actions"))){
            Map<String,Object> action=new LinkedHashMap<>(DraftBusinessRules.asMap(raw));
            if(action.get("layoutId")!=null){
                List<Feature> matches=markers.getOrDefault(String.valueOf(action.get("layoutId")),Collections.emptyList());
                if(matches.size()!=1||!matches.get(0).isComplete()){List<String> removed=DraftBodyCleanup.removedLayoutOperations(result,action);if(!removed.isEmpty()){action.put("status","REMOVED_WITH_BODY_SCOPE");action.put("bodyOperationIds",removed);action.put("generatedId",null);}else{action.put("status","MISSING_LAYOUT_CONTROL");action.put("generatedId",null);current.put("status","unavailable");}}
                else{
                    String start=matches.get(0).getStartId(),paragraph=start.substring(0,start.lastIndexOf("/w:bookmarkStart"));action.put("generatedId",paragraph);Paragraph node=result.getIndex().paragraph(paragraph);String kind=String.valueOf(action.get("action"));
                    boolean changed="page_break_before".equals(kind)&&"RELEASED_VERIFIED_SCT_TITLE_MIGRATION".equals(action.get("status"))&&!node.hasCompactEmptyLayoutSpacing()||"compact_verified_empty_spacing".equals(kind)&&!node.hasCompactEmptyLayoutSpacing()||"keep_verified_row_together".equals(kind)&&!node.hasNativeRowCohesion()||"compact_verified_row_gaps".equals(kind)&&!node.hasCompactNativeRowGaps()||"compact_verified_cleared_spacing".equals(kind)&&!node.hasCompactClearedLayoutSpacing()||"keep_verified_paragraph_with_next".equals(kind)&&!node.hasNativeKeepNext()||"keep_verified_heading_flow".equals(kind)&&!node.hasNativeHeadingFlow()||"release_verified_trailing_page_break".equals(kind)&&!node.hasReleasedNativeTrailingPageBreak()||"keep_verified_cleared_guidance_with_next".equals(kind)&&!node.hasClearedNativeKeepNext()||"page_break_before_verified_heading".equals(kind)&&!node.hasNativeHeadingPageBreak()||"normalize_verified_latin_font_hint".equals(kind)&&!node.hasNormalizedNativeLatinFontHints()||"normalize_verified_latin_font_slot".equals(kind)&&!node.hasNormalizedNativeLatinFontSlots()||"keep_verified_cell_paragraph_with_next".equals(kind)&&!node.hasNativeCellKeepNext()||"keep_verified_cell_paragraph_widows".equals(kind)&&!node.hasNativeWidowControl()||"keep_verified_body_paragraph_widows".equals(kind)&&!node.hasNativeWidowControl()||"keep_verified_boundary_body_lines".equals(kind)&&!node.hasNativeBodyLines();
                    if(changed){action.put("status","CHANGED_LAYOUT_CONTROL");current.put("status","unavailable");}
                }
            }
            actions.add(action);
        }
        Map<String,Object> stories=DraftBusinessRules.asMap(current.get("nativeStories"));if(!stories.isEmpty()){Map<String,Object> nextStories=new LinkedHashMap<>(stories);nextStories.put("parentDocxSha256",stories.get("docxSha256"));nextStories.put("docxSha256",result.getDocxSha256());for(Map.Entry<String,Object> entry:DraftBusinessRules.asMap(stories.get("entryHashes")).entrySet())if(!Objects.equals(entry.getValue(),result.getIndex().getEntryHashes().get(entry.getKey()))){nextStories.put("status","native_story_part_changed");current.put("status","unavailable");}current.put("nativeStories",nextStories);}
        current.put("actions",actions);List<Object> rows=withSourceRemovals(previousJson,result,current);
        if(Objects.equals(previous.get("docxSha256"),result.getOriginalSourceSha256())&&!result.getLedger().isEmpty()){List<Object> edits=JsonUtils.readList(JsonUtils.write(result.getLedger()),Object.class);List<String> operations=new ArrayList<>();for(AppliedEdit edit:result.getLedger())operations.add(edit.getOperationId());rows.add(DraftBusinessRules.map("kind","native_editor_derivation","status","VERIFIED_EDITOR_RESULT","parentDocxSha256",result.getOriginalSourceSha256(),"docxSha256",result.getDocxSha256(),"operationIds",operations,"nativeEdits",edits,"nativeEditsSha256",DraftAdoption.hash(JsonUtils.write(edits))));}
        return DraftBodyCleanup.preserveHistory(previousJson,rows);
    }
